from pathlib import Path
import json,ast,html
r=Path(__file__).parent;o=r/'dist';ps=json.loads((r/'projects.json').read_text());by={p['slug']:p for p in ps}
order=['haven','forge','aurelia','atelier','bloom','kora','form-and-field','roots','wayfarer','daily-ritual','northline','common-ground','zest','axis','coast-and-trail','sunpop','signal-studio','willow-and-vale','table','shift']
ps=[by[k] for k in order]
fiverr='https://www.fiverr.com/ay_obam1'
def rail(active=None):
 links=''.join(f'<a href="/work/{p["slug"]}/" {"aria-current=page" if active==p["slug"] else ""}><span>{i+1:02}</span>{p["name"]}</a>' for i,p in enumerate(ps))
 return f'''<a class="skip" href="#main">Skip to content</a><aside class="rail"><a class="wordmark" href="/" aria-label="Ayobami portfolio home">Ayobami<span>®</span></a><p class="rail-intro">Publication &<br>editorial design.</p><nav aria-label="Main navigation" class="rail-nav"><a href="/#work">Selected work</a><a href="/#about">About</a><a href="/#contact">Contact</a></nav><nav class="project-index" aria-label="Project index"><p>PROJECT INDEX / {len(ps):02}</p>{links}</nav><a class="rail-contact" href="{fiverr}" target="_blank" rel="noopener noreferrer">Let’s work together</a><span class="rail-foot">Print. Digital. Every page.</span></aside>'''
# No registered trademark claims: the small mark is a plain asterisk.
footer=f'''<footer><p>Publication & editorial design<br>© 2026 Ayobami</p><a href="{fiverr}" target="_blank" rel="noopener noreferrer">Enquiries on Fiverr</a><a href="#main">Back to top</a></footer>'''
def shell(title,desc,body,active=None):
 return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#ffffff"><title>{html.escape(title)}</title><meta name="description" content="{html.escape(desc,quote=True)}"><link rel="icon" type="image/svg+xml" href="data:image/svg+xml,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 32 32'%3E%3Crect width='32' height='32' fill='white'/%3E%3Ctext x='5' y='26' font-family='Georgia' font-size='29' fill='black'%3Ea%3C/text%3E%3C/svg%3E"><link rel="stylesheet" href="/style.css"><script src="/app.js" defer></script></head><body>{rail(active).replace('®','*')}<div class="content">{body}{footer}</div></body></html>'''
filters=''.join(f'<button type="button" data-filter="{x}" aria-pressed="{str(x=="All").lower()}">{x if x=="All" else x+"s"}</button>' for x in ['All','Brochure','Catalog','Magazine','Report','Guide'])
cards=''
for i,p in enumerate(ps):
 slug=p['slug']
 # Different presentations: lifestyle mockups, single covers, and flat publication compositions.
 if slug in ['sunpop','shift','table']:
  inside=f'<img class="single-cover" src="/assets/{slug}/page-1.webp" alt="{p["name"]} cover design" width="1191" height="1684" loading="lazy">'
 elif slug=='daily-ritual':
  inside=f'<div class="paired-pages"><img src="/assets/{slug}/page-1.webp" alt="Daily Ritual beauty catalog cover" width="1191" height="1684" loading="lazy"><img src="/assets/{slug}/page-4.webp" alt="Daily Ritual serum product page" width="1191" height="1684" loading="lazy"></div>'
 else:
  inside=f'<img class="mockup" src="/assets/{slug}/cover.webp" alt="{p["name"]} cover and selected publication pages" width="1600" height="1050" loading="{"eager" if i==0 else "lazy"}">'
 cards+=f'''<article class="project-card tile-{slug}" data-category="{p['kind']}" data-search="{html.escape(p['name']+' '+p['kind']+' '+p['desc']+' '+p['details'],quote=True)}"><a href="/work/{slug}/" class="project-link"><div class="artwork" style="--project-color:{p['bg']}">{inside}<span class="view-label">Explore project</span></div><div class="card-caption"><span class="project-number">{i+1:02}</span><h2>{p['name']}</h2><span class="card-kind">{p['kind']} design</span></div></a></article>'''
body=f'''<main id="main"><header class="introduction"><div><p class="eyebrow">SELECTED PUBLICATIONS / 2026</p><h1>Design that makes<br>every page matter.</h1></div><p>Brochures. Catalogs. Magazines. Reports.<br>Distinct layouts for stories worth sharing.</p></header><section id="work" class="work"><div class="work-controls"><div class="filters" role="group" aria-label="Filter projects">{filters}</div><span id="project-count" aria-live="polite">{len(ps)} projects</span></div><label class="project-search">Find a project<input id="project-search" type="search" placeholder="Search names, industries or design techniques" autocomplete="off"></label><div class="collection-summary"><span>{len(ps)} publications</span><span>{sum(int(p["length"]) for p in ps)} pages & flat sheets</span><span>{len(set(p["kind"] for p in ps))} design categories</span></div><div class="project-grid">{cards}</div><div id="no-results" hidden><h2>No matching publications.</h2><p>Try another phrase or reset your filters.</p><button id="reset-filters" type="button" class="button">Show all projects</button></div></section><section id="about" class="about"><p class="eyebrow">A LITTLE ABOUT ME</p><div class="about-columns"><h2>I’m Ayobami.<br>I bring structure,<br>rhythm and character<br>to the page.</h2><div><p>I design brochures, catalogs, magazines and business reports in Adobe InDesign. My work centres on thoughtful typography, purposeful image placement and a clear reading experience.</p><p>Each publication gets its own visual language—from a bold culture magazine to a quietly refined product catalog.</p><p class="small-note">Adobe InDesign / Print & digital layouts</p></div></div></section><section class="services"><p class="eyebrow">WHAT I DESIGN</p><div><h3>Brochures & company profiles</h3><p>Clear introductions to your business, service or destination.</p></div><div><h3>Product catalogs</h3><p>Consistent product presentation and easy-to-follow information.</p></div><div><h3>Magazines & editorial layouts</h3><p>A distinct visual voice with rhythm across features and spreads.</p></div><div><h3>Business reports</h3><p>Readable narrative, figures, charts and longer documents.</p></div></section><section class="process"><p class="eyebrow">FROM CONTENT TO PUBLICATION</p><h2>A clear process, from the first brief.</h2><div class="process-grid"><article><span>01 / BRIEF</span><h3>Set the direction</h3><p>We review your content, audience, brand assets, page count and intended format.</p></article><article><span>02 / LAYOUT</span><h3>Build the visual language</h3><p>Typography, image treatment and page structure establish the direction for the publication.</p></article><article><span>03 / REVIEW</span><h3>Refine the details</h3><p>Consolidated feedback helps refine the layout, content flow and consistency across pages.</p></article><article><span>04 / HANDOVER</span><h3>Prepare the agreed files</h3><p>The final handover follows the formats and specifications agreed for your project.</p></article></div></section><section class="faqs"><p class="eyebrow">BEFORE WE START</p><h2>A few practical questions</h2><details><summary>What should I send for a quote?</summary><p>Your approximate page count, final or draft content, brand assets, reference designs, deadline and intended use: print, digital or both.</p></details><details><summary>Can you work with an existing publication?</summary><p>Yes. Share the existing document and explain whether you need a redesign, updated content or a layout that follows the current style.</p></details><details><summary>Can the final document be editable?</summary><p>Editable InDesign files can be included when agreed in the project scope. PDF exports and any required linked assets can be discussed as part of the handover.</p></details><details><summary>Do you also write the content?</summary><p>The service focuses on publication design. Please supply the text, product information and data you want included, and confirm whether any additional content work is needed.</p></details><details><summary>Can I see a complete publication?</summary><p>Every project here includes its full page collection, an interactive reader and a downloadable PDF viewing copy.</p></details></section><section id="contact" class="contact"><p class="eyebrow">YOUR NEXT PUBLICATION</p><h2>Let’s make<br><em>something worth reading.</em></h2><div><p>Share your content, page count, brand assets and deadline.<br>We’ll discuss the layout and scope together.</p><a class="button" href="{fiverr}" target="_blank" rel="noopener noreferrer">Discuss your project</a></div><a class="secondary-link" href="https://www.fiverr.com/ay_obam1/design-catalogs-magazines-business-reports-and-brochures-in-adobe-indesign" target="_blank" rel="noopener noreferrer">Brochure & report service on Fiverr</a></section></main>'''
(o/'index.html').write_text(shell('Ayobami — Publication & Editorial Design','Selected brochure, catalog, magazine and business report design by Ayobami.',body))
for i,p in enumerate(ps):
 slug=p['slug'];pages=list(range(int(p['length'])));nextp=ps[(i+1)%len(ps)]
 figures=''.join(f'''<figure class="detail-page page-position-{j}"><button type="button" data-image="/assets/{slug}/page-{n+1}.webp" data-caption="{p['name']} — {'Cover' if n==0 else 'Page '+str(n+1)}" aria-label="Enlarge {p['name']} {'cover' if n==0 else 'page '+str(n+1)}"><img src="/assets/{slug}/page-{n+1}.webp" alt="{p['name']} {'cover' if n==0 else 'page '+str(n+1)} publication layout" width="1191" height="1684" loading="lazy"></button><figcaption>{'Cover' if n==0 else 'Page '+str(n+1)}</figcaption></figure>''' for j,n in enumerate(pages))
 body=f'''<main id="main" class="project-detail"><header class="detail-heading"><a href="/#work" class="back-link">All publications</a><p class="eyebrow">{p['kind'].upper()} DESIGN / {p['length']} {'FLAT SIDES' if p['slug'] in ['haven','aurelia','wayfarer'] else 'PAGES'}</p><h1>{p['name']}</h1><p>{p['subtitle']}</p></header><div class="detail-hero"><img src="/assets/{slug}/cover.webp" alt="{p['name']} publication presentation" width="1600" height="1050" fetchpriority="high"></div><section class="project-story"><h2>{p['desc']}</h2><div><p>{p['approach']}</p><dl><dt>Design focus</dt><dd>{p['details']}</dd><dt>Format</dt><dd>Editable InDesign layout / PDF publication</dd></dl><div class="project-actions"><button type="button" class="button open-reader">Read complete publication</button><a class="secondary-link" href="/assets/{slug}/full-publication.pdf" target="_blank" rel="noopener">Download full PDF</a></div><a class="secondary-link" href="/assets/{slug}/selected-pages.pdf" target="_blank" rel="noopener">View selected pages as PDF</a></div></section><section class="page-section"><div class="page-section-heading"><h2>Inside the publication</h2><p>{p["length"]} {"flat sides" if slug in ["haven","aurelia","wayfarer"] else "pages"}. Select a page to open the reader.</p></div><div class="detail-pages" style="--project-color:{p['bg']}">{figures}</div></section><section class="next-project"><span class="eyebrow">NEXT PUBLICATION</span><a href="/work/{nextp['slug']}/"><h2>{nextp['name']}</h2><p>{nextp['kind']} design</p></a></section></main><dialog class="lightbox" aria-label="Publication reader"><div class="reader-toolbar"><span class="reader-title">{p["name"]}</span><button class="zoom-out" type="button" aria-label="Zoom out">−</button><button class="zoom-reset" type="button">Fit</button><button class="zoom-in" type="button" aria-label="Zoom in">+</button><button class="close-dialog" type="button" aria-label="Close publication reader">Close</button></div><div class="reader-stage"><img alt=""></div><div class="reader-navigation"><button class="previous-page" type="button">Previous</button><label>Page <select class="page-select" aria-label="Jump to page"></select><span class="page-total"></span></label><button class="next-page" type="button">Next</button></div><p class="reader-caption"></p><p class="reader-hint">Use left and right arrow keys to turn pages. Escape closes the reader.</p></dialog>'''
 (o/'work'/slug).mkdir(parents=True,exist_ok=True)
 (o/'work'/slug/'index.html').write_text(shell(p['name']+' — Ayobami',p['desc'],body,slug))
(o/'404.html').write_text(shell('Page not found — Ayobami','Return to the publication portfolio.','<main id="main" class="missing"><h1>This page isn’t here.</h1><a class="button" href="/">Back to the portfolio</a></main>'))
print('Expanded gallery and 20 complete publication pages')
